    });
    for (const [x, z, rot] of [
      [-2.7, -1.7, 0],
      [2.7, 1.7, Math.PI],
      [-1.7, 2.7, Math.PI / 2],
      [1.7, -2.7, -Math.PI / 2],
    ]) {
      const bench = new THREE.Group();
      const seat = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.045, 0.18), benchMat);
      seat.position.y = 0.11;
