        emissiveIntensity: 0.4,
        transparent: true,
        opacity: 0.65,
      }),
    );
    base.position.y = 0.012;
    group.add(base);

    car.scale.setScalar(0.86);
    group.add(car);
    group.position.set(0, 0.26, 0);
    this.scene.add(group);

