}

.player-avatar {
  flex: 0 0 auto;
  width: 34px;
  height: 34px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  font-weight: 800;
  font-size: 15px;
  color: #082026;
  background: var(--pc);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35), 0 4px 12px color-mix(in srgb, var(--pc) 30%, transparent);
  position: relative;
}

.player-avatar .bot-dot {
  position: absolute;
  right: -3px;
  bottom: -3px;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #0b282e;
  border: 1px solid var(--pc);
  display: grid;
  place-items: center;
  color: var(--pc);
}

.player-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.player-line {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
}

.player-name {
  font-weight: 600;
  font-size: 12.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.player-age {
  font-size: 9px;
  color: var(--cream-faint);
  white-space: nowrap;
}

.player-cash {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.01em;
