  color: var(--cream-faint);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-variant-numeric: tabular-nums;
}

.player-badge {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--pc);
  border: 1px solid color-mix(in srgb, var(--pc) 50%, transparent);
  padding: 1px 4px;
  border-radius: 4px;
  white-space: nowrap;
}

.player-card.retired {
  opacity: 0.62;
}

/* ---------------------------------------------------------------- turn bar */

.turnbar {
  position: absolute;
  z-index: 14;
  top: calc(132px + env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 13px;
