  }

  .title-screen {
    padding: calc(80px + env(safe-area-inset-top)) 6vw calc(30px + env(safe-area-inset-bottom));
    align-items: flex-end;
  }

  .title-screen::before {
    background:
      linear-gradient(0deg, rgba(3, 16, 19, 0.97) 0%, rgba(3, 16, 19, 0.75) 36%, rgba(3, 16, 19, 0.1) 68%, transparent 90%),
      linear-gradient(180deg, rgba(3, 16, 19, 0.5), transparent 25%);
  }

  .title-copy {
    width: 100%;
    max-width: 520px;
  }

  .title-copy h1 {
    font-size: clamp(46px, 13vw, 74px);
  }

  .title-desc {
    display: none;
  }

  .title-actions {
    margin-top: 20px;
  }

  .title-meta {
    margin-top: 16px;
  }

  .modal-card {
    padding: 18px;
    border-radius: 18px;
  }

  .setup-player {
    grid-template-columns: 18px minmax(70px, 1fr) auto minmax(96px, 0.85fr);
