private fillHouses(
  group: THREE.Group,
  tileIndex: number,
  level: number,
  ownerColor: string,
): void {
  const count = Math.min(level, MAX_LEVEL);
  const { side } = tilePosition(tileIndex);
  for (let i = 0; i < count; i += 1) {
    const house = this.createHouse(ownerColor, i === count - 1 && level >= 3);
